js:
var d = []
var page = MY_PAGE
var 切换 = getVar("切换x", "0")
var 分类 = ["全部分类=0", "新闻=5", "音乐台=14", "交通=1", "经济台=11", "文艺台=4", "曲艺台=8", "体育台=2", "生活台=10", "外语台=3", "都市台=13", "综合台=12", "其它台=15", "方言台=6", "旅游台=7"]
var 地方 = ["全部地区=0", "北京=110000", "河北=130000", "山西=140000", "内蒙古=150000" + "辽宁=210000" + "吉林=220000" + "黑龙江=230000" + "上海=310000" + "江苏=320000" + "浙江=330000" + "安徽=340000", "福建=350000", "江西=360000", "山东=370000", "河南=410000", "湖北=420000", "湖南=430000", "广东=440000", "广西=450000", "海南=460000", "重庆=500000", "四川=510000", "贵州=520000", "云南=530000", "西藏=540000", "陕西=610000", "甘肃=620000", "宁夏=640000", "新疆=650000"]
if (page == 1) {
    d.push({
        title: 切换 === "1" ? '““””<b>' + '∧'.fontcolor("#FF0000") + '</b>' : '““””<b>' + 'V'.fontcolor("#1aad19") + '</b>',
        col_type: "scroll_button",
        url: $("#noLoading#").lazyRule((切换) => {
            putVar("切换x", 切换 == "1" ? "0" : "1");
            refreshPage(true);
            return "hiker://empty"
        }, 切换)
    })
    if (getVar("分类u", "") == "") {
        let url1 = 分类[0].replace(/.*=/, "")
        putVar("分类u", url1);
    }
    if (getVar("地方u", "") == "") {
        let url1 = 地方[0].replace(/.*=/, "")
        putVar("地方u", url1);
    }
    分类.forEach((it) => {
        var title = it.replace(/=\d+/, "")
        var url = it.replace(/.*=/, "")
        d.push({
            title: getVar("分类b", 分类[0].replace(/=\d+/, "")) === title ? "““" + title + "””" : title,
            col_type: "scroll_button",
            url: $("#noLoading#").lazyRule((title, url) => {
                putVar("分类b", title);
                putVar("分类u", url); //log(input)
                refreshPage(true);
                return "hiker://empty"
            }, title, url),
        })
    })
    if (切换 == "1") {
        d.push({
            col_type: "blank_block"
        });
        地方.forEach((it) => {
            var title = it.replace(/=.*/, "")
            var url = it.replace(/.*=/, "")            
            d.push({
                title: getVar("地方b", 地方[0].replace(/=.*/, "")) === title ? "““" + title + "””" : title,
                col_type: "scroll_button",
                url: $("#noLoading#").lazyRule((title, url) => {
                    putVar("地方b", title);
                    putVar("地方u", url)
                    refreshPage(true);
                    return "hiker://empty"
                }, title, url),
            })
        })
    }
}
var data1 = "https://mobile.ximalaya.com/radio-first-page-app/search?categoryId=" + getVar("分类u") + "&isHttps=true&locationId=" + getVar("地方u") + "&locationTypeId=0&pageNum=1&pageSize=1000"; //log(data1)
var json = JSON.parse((request(data1))); //log(json)
json.data.radios.map((it) => {
    d.push({
        title: it.name,
        //pic_url: it.coverLarge,
        pic_url: "https://hikerfans.com/tubiao/more/258.png",
        url: it.playUrl.aac64 + "#isMusic=true#",
        col_type: "icon_2_round",
    })
})
setResult(d)
